mapper.select:
SELECT c.id AS customer_id, c.customer_name, c.mobile, c.status, c.intent_level, c.heat_score, advisor.nickname AS advisor_name, manager.nickname AS manager_name FROM crm_customer c LEFT JOIN sys_user advisor ON c.advisor_id = advisor.id LEFT JOIN sys_user manager ON c.manager_id = manager.id WHERE c.deleted = 0 AND c.heat_score >= 80
AND c.advisor_id = #{advisorId}
AND c.manager_id = #{managerId}
ORDER BY c.heat_score DESC, c.updated_at DESC
